"""The EPT Hankel-block tables generated by ``tools/pt_autogen`` (``tables/ept/hankel_<22|13>.dat``).

The meaning of a block ``(l, n, m)`` and the sign convention of its entries are stated in the
headers of the tables.
"""
import os

import numpy as np

from .table_text import fraction, records

TABLE_DIR = os.path.join(os.path.dirname(__file__), 'tables', 'ept')


def read_tables(prefix):
    """``(names, lnm, table)`` of the blocks ``<prefix>_l_n_m`` (``prefix`` '22' or '13').

    ``lnm`` is ``(nblocks, 3)`` int64, ``table`` ``(nblocks, nterms, 7)``: per row the powers of
    (mu, f, b1, b2, bG2, bGamma3) and the coefficient (the float64 of the exact rational),
    zero-padded rows at the end.
    """
    lines = records(os.path.join(TABLE_DIR, f'hankel_{prefix}.dat'))
    blocks = {r[1]: [int(v) for v in r[2:5]] for r in lines if r[0] == 'block'}      # name -> [l, n, m]
    terms = {name: [] for name in blocks}
    for r in lines:
        if r[0] == 'term':
            terms[r[1]].append([float(int(e)) for e in r[2:8]] + [float(fraction(r[8]))])
    names = list(blocks)
    table = np.zeros((len(names), max(map(len, terms.values())), 7))
    for i, b in enumerate(names):
        table[i, :len(terms[b])] = terms[b]
    return names, np.array([blocks[b] for b in names], dtype=np.int64), table
